private void FilterRoom()
{
    string strCondition = "";

    if (lookupAreaID.EditValue != null)
        strCondition = "AreaID = '" + lookupAreaID.EditValueString + "'";
    else if (!string.IsNullOrWhiteSpace(strOfficeFilter))
    {
        // SIM_Room không có cột OfficeID, lọc phòng theo AreaID thuộc chi nhánh được quyền
        DataRow[] drwArea = SIM_AreaService.Table.Select(strOfficeFilter);
        if (drwArea != null && drwArea.Length > 0)
        {
            string strAreaList = "";
            int i;
            for (i = 0; i < drwArea.Length; i++)
            {
                if (drwArea[i]["AreaID"] == DBNull.Value)
                    continue;
                if (strAreaList != "")
                    strAreaList += ",";
                strAreaList += "'" + drwArea[i]["AreaID"].ToString().Replace("'", "''") + "'";
            }
            if (strAreaList != "")
                strCondition = "AreaID IN (" + strAreaList + ")";
            else
                strCondition = "1=0";
        }
        else
            strCondition = "1=0";
    }

    lookupRoomID.RowFilter = strCondition;
}
